// npm run build:licenses: writes THIRD_PARTY_LICENSES with the full licence text of every package bundled into the
// gateway Worker (its runtime dependencies, React's scheduler, and Tailwind CSS, whose base styles are in the compiled
// stylesheet).
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

export const gatewayDir = join(dirname(fileURLToPath(import.meta.url)), '..')
export const LICENSES_FILE = join(gatewayDir, 'THIRD_PARTY_LICENSES')

/** The packages whose code or generated output ships in the deployed Worker. */
export function bundledPackages() {
  const manifest = JSON.parse(readFileSync(join(gatewayDir, 'package.json'), 'utf8'))
  return [...Object.keys(manifest.dependencies), 'scheduler', 'tailwindcss'].sort()
}

function licenceText(name) {
  const directory = join(gatewayDir, 'node_modules', name)
  const file = readdirSync(directory).find((entry) => /^(licen[cs]e|copying)(\.(md|txt))?$/i.test(entry))
  if (!file) throw new Error(`No licence file in ${name}`)
  return readFileSync(join(directory, file), 'utf8').trim()
}

export function licencesDocument() {
  const sections = bundledPackages().map((name) => {
    const manifest = JSON.parse(readFileSync(join(gatewayDir, 'node_modules', name, 'package.json'), 'utf8'))
    return [`${name} ${manifest.version} (${manifest.license})`, '-'.repeat(72), '', licenceText(name)].join('\n')
  })
  return [
    'Third-party licences of the Insulin Apps gateway',
    '',
    'The deployed gateway Worker bundles the packages below. Generated by `npm run build:licenses`: do not edit.',
    'Material copied into the source (shadcn/ui, Lucide icon shapes) is listed in NOTICE.',
    '',
    '',
    sections.join('\n\n\n'),
    '',
  ].join('\n')
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(LICENSES_FILE, licencesDocument())
  process.stdout.write(`Wrote ${LICENSES_FILE}\n`)
}
